"""CRUD endpoints for members."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Member
from app.schemas import MemberCreate, MemberRead, MemberUpdate

router = APIRouter(prefix="/members", tags=["members"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, member_id: int) -> Member:
    member = session.get(Member, member_id)
    if member is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Member not found")
    return member


@router.get("", response_model=list[MemberRead])
def list_members(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Member]:
    query = select(Member).order_by(Member.id).offset(offset).limit(limit)
    return list(session.scalars(query))


@router.post("", response_model=MemberRead, status_code=status.HTTP_201_CREATED)
def create_member(payload: MemberCreate, session: SessionDep) -> Member:
    member = Member(**payload.model_dump())
    session.add(member)
    session.commit()
    session.refresh(member)
    return member


@router.get("/{member_id}", response_model=MemberRead)
def get_member(member_id: int, session: SessionDep) -> Member:
    return _get_or_404(session, member_id)


@router.patch("/{member_id}", response_model=MemberRead)
def update_member(
    member_id: int,
    payload: MemberUpdate,
    session: SessionDep,
) -> Member:
    member = _get_or_404(session, member_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(member, key, value)
    session.commit()
    session.refresh(member)
    return member


@router.delete("/{member_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_member(member_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, member_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

from fastapi.testclient import TestClient

PAYLOAD = {
    "name": "example name",
    "email": "example email",
}


def test_create_and_get_member(client: TestClient) -> None:
    response = client.post("/members", json=PAYLOAD)
    assert response.status_code == 201, response.text
    created = response.json()
    assert created["name"] == "example name"
    assert created["email"] == "example email"
    fetched = client.get(f"/members/{created['id']}")
    assert fetched.status_code == 200
    assert fetched.json()["id"] == created["id"]


def test_list_member_supports_pagination(client: TestClient) -> None:
    for _ in range(3):
        assert client.post("/members", json=PAYLOAD).status_code == 201
    page = client.get("/members", params={"limit": 2, "offset": 1})
    assert page.status_code == 200
    assert len(page.json()) == 2


def test_update_member(client: TestClient) -> None:
    created = client.post("/members", json=PAYLOAD).json()
    response = client.patch(
        f"/members/{created['id']}", json={"name": "updated name"}
    )
    assert response.status_code == 200
    assert response.json()["name"] == "updated name"


def test_delete_member(client: TestClient) -> None:
    created = client.post("/members", json=PAYLOAD).json()
    assert client.delete(f"/members/{created['id']}").status_code == 204
    assert client.get(f"/members/{created['id']}").status_code == 404


def test_unknown_member_returns_404(client: TestClient) -> None:
    assert client.get("/members/999999").status_code == 404


def test_create_member_rejects_missing_required_fields(client: TestClient) -> None:
    assert client.post("/members", json={}).status_code == 422

